        for (int i = 0; i < 11; i++) {
            eleven.add(new int[]{1, 1});
        }
        adjudicate("req-b3", "adj-b2", "operator-a", eleven).andExpect(status().isBadRequest());
        assertThat(adjudicationCount()).isZero();
